CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student');
CREATE TABLE menu(id INTEGER PRIMARY KEY AUTOINCREMENT,item_name TEXT NOT NULL,price REAL NOT NULL,available INTEGER NOT NULL DEFAULT 1,preparation_time INTEGER NOT NULL DEFAULT 5);
CREATE TABLE orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,token INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'WAITING',total REAL NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,menu_id INTEGER NOT NULL,quantity INTEGER NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(menu_id) REFERENCES menu(id));